import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"IAA / DAX","description":"","frontmatter":{},"headers":[],"relativePath":"notes/hardware/accelerator/IAA.md","filePath":"notes/hardware/accelerator/IAA.md"}'),i={name:"notes/hardware/accelerator/IAA.md"};function n(s,e,c,l,h,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="iaa-dax" tabindex="-1">IAA / DAX <a class="header-anchor" href="#iaa-dax" aria-label="Permalink to &quot;IAA / DAX&quot;">​</a></h1><blockquote><p>A major advancement in SPR is the introduction of Data Accelerator Complex (DAC) [29]. As illustrated in the left part of Fig. 1, a DAC tile integrates four built-in accelerators—QAT, DLB, DSA, and IAA—along with cache-coherent interconnect, and is dedicated to each SPR SoC chiplet.</p></blockquote><h2 id="qpl" tabindex="-1">QPL <a class="header-anchor" href="#qpl" aria-label="Permalink to &quot;QPL&quot;">​</a></h2><blockquote><p>The Intel® Query Processing Library (Intel® QPL) is an open-source library to provide high-performance query processing operations on Intel CPUs. Intel® QPL is aimed to support capabilities of the new Intel® In-Memory Analytics Accelerator (Intel® IAA) available on Next Generation Intel® Xeon® Scalable processors, codenamed Sapphire Rapids processor, such as very high throughput compression and decompression combined with primitive analytic functions, as well as to provide highly-optimized SW fallback on other Intel CPUs. Intel QPL primarily targets applications such as big-data and in-memory analytic databases.</p></blockquote><h2 id="iaa" tabindex="-1">IAA <a class="header-anchor" href="#iaa" aria-label="Permalink to &quot;IAA&quot;">​</a></h2><p>IAA 指 Intel In-Memory Analytics Accelerator，是一种集成在部分 Intel Xeon 处理器中的片上硬件加速器，用于把压缩、解压缩、扫描、过滤、CRC 等数据密集型操作从通用 CPU 核心卸载出去。 参见 <a href="https://ieeexplore.ieee.org/document/11096374" target="_blank" rel="noreferrer">IAA (IEEE)</a>。</p><blockquote><p>As IAA is integrated with CPUs as an on-chip accelerator, it can directly access the CPU&#39;s cache and memory in a cache-coherent manner, offering low latency and power consumption with reduced programming complexity compared to off-chip accelerators.</p></blockquote><h2 id="hardware-architecture" tabindex="-1">Hardware Architecture <a class="header-anchor" href="#hardware-architecture" aria-label="Permalink to &quot;Hardware Architecture&quot;">​</a></h2><p><img src="https://raw.githubusercontent.com/sandyyyz/Image-hosting/main/img/IAA.png" alt="IAA_arch"></p><p>单个 IAA 实例由以下部分组成：</p><ol><li>八个 Work Queue（WQ），包括可被多个 client 共享的 Shared WQ（SWQ），以及绑定到单个 client 的 Dedicated WQ（DWQ）；</li><li>八个 Engine（ENG）；</li><li>Analytics/(De)Compression pipe arbiter；</li><li>Pipe；</li><li>Address Translation Cache；</li><li>DMA engine。</li></ol><h3 id="workflow" tabindex="-1">workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;workflow&quot;">​</a></h3><blockquote><p>The ENGs fetch descriptors from the WQs, with arbiters ensuring Quality of Service (QoS) and fairness. The ENG forwards the job descriptor to the appropriate processing pipe, as determined by the arbiter, and manages the DMA transfer of data between system memory and either the analytics or compression pipe. The fundamental operational unit in IAA is a group, which can include any combination of WQs and ENGs, up to the maximum capacity supported by the IAA.</p></blockquote><h2 id="software-architecture" tabindex="-1">Software Architecture <a class="header-anchor" href="#software-architecture" aria-label="Permalink to &quot;Software Architecture&quot;">​</a></h2><blockquote><p>Like DSA, IAA uses the Intel Data Accelerator Driver (IDXD), a Linux kernel module responsible for detecting and initializing IAA devices. IDXD manages essential control operations and exposes them to user-space applications via the libaccel-config API library, simplifying configuration tasks such as setting up groups.</p></blockquote><blockquote><p>When creating job descriptors, QPL provides three execution paths: (1) the hardware path, which executes jobs on IAA; (2) the software path, which runs them on a CPU core; and (3) the auto path, which attempts to use IAA but falls back to the CPU in case of failure (e.g., unsupported operations or IAA initialization fails).</p></blockquote><h2 id="supporting-operations" tabindex="-1">Supporting Operations <a class="header-anchor" href="#supporting-operations" aria-label="Permalink to &quot;Supporting Operations&quot;">​</a></h2><p><img src="https://raw.githubusercontent.com/sandyyyz/Image-hosting/main/img/IAA-support-operations.png" alt="IAA-supporting-Operations"></p>',18)])])}const A=a(i,[["render",n]]);export{u as __pageData,A as default};
